using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Binary.Streams;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// C120: a package keeps the read order of its names/flags after the procedure tree (ProcedureTreeDataOrder, C82), but a
// copy lost it, so DeepCopy of the 5 packages of Starfield.esm that don't hold them by index wrote them sorted (e.g.
// PilotDockingPackageIgnoreCombat: UNAM #88 25 instead of 26). Copies now keep the order (as the Skyrim and Fallout 4
// ports, C117); it is still not compared or hashed.
// Each package is read whole with both readers; the record, a DeepCopy of it and an override copy write back byte for byte.
public class PackageCopyKeepsOrderTests
{
    // PilotDockingPackageIgnoreCombat (07D422:Starfield.esm)
    private const string Pilot = "";

    // LC043_PursuitShipsIgnoreCombatUntilEscape (0DF18B:Starfield.esm)
    private const string Pursuit = "";

    private static IEnumerable<IPackageGetter> Read(string hex) => ReadBoth<IPackageGetter>(Record("PACK", Hex(hex)),
        f => Package.CreateFromBinary(f), (s, p) => PackageBinaryOverlay.PackageFactory(s, p));

    private static byte[] Content(IPackageGetter pack)
        => GameConstants.Starfield.MajorRecord(Write(w => pack.WriteToBinary(w))).Content.ToArray();

    [Theory]
    [InlineData(Pilot)]
    [InlineData(Pursuit)]
    public void DeepCopy_WritesBackByteForByte(string hex)
    {
        foreach (var pack in Read(hex))
        {
            Content(pack).ShouldBe(Hex(hex));
            var copy = pack.DeepCopy();
            Content(copy).ShouldBe(Hex(hex));
            Content(copy.DeepCopy()).ShouldBe(Hex(hex));
            var into = new Package(copy.FormKey, StarfieldRelease.Starfield);
            into.DeepCopyIn(pack, out _);
            Content(into).ShouldBe(Hex(hex));
        }
    }

    [Theory]
    [InlineData(Pilot)]
    [InlineData(Pursuit)]
    public void ReadOrder_IsNotData(string hex)
    {
        var read = Package.CreateFromBinary(new MutagenFrame(new MutagenMemoryReadStream(Record("PACK", Hex(hex)), Meta())));
        var copy = read.DeepCopy();
        copy.ProcedureTreeDataOrder.ShouldBe(read.ProcedureTreeDataOrder);
        copy.Equals(read).ShouldBeTrue();
        copy.GetHashCode().ShouldBe(read.GetHashCode());
        // Without the read order: other bytes, same data and hash
        var sorted = read.DeepCopy();
        sorted.ProcedureTreeDataOrder = null;
        Content(sorted).ShouldNotBe(Hex(hex));
        var reRead = Package.CreateFromBinary(new MutagenFrame(new MutagenMemoryReadStream(Record("PACK", Content(sorted)), Meta())));
        reRead.Equals(read).ShouldBeTrue();
        read.Equals(reRead).ShouldBeTrue();
        reRead.GetHashCode().ShouldBe(read.GetHashCode());
    }
}
